sp_page.css:
/* Insurance Claim Hub - Professional Login */

body {
    background: linear-gradient(135deg, #eef6ff, #f8fbff) !important;
}

main.page {
    min-height: 100vh !important;
    background: linear-gradient(135deg, #eef6ff, #f8fbff) !important;
}

/* Login card */
.panel {
    border: none !important;
    border-radius: 18px !important;
    box-shadow: 0 12px 35px rgba(30, 90, 160, 0.15) !important;
    overflow: hidden !important;
}

/* Login heading */
.panel-heading {
    background: #ffffff !important;
    color: #123b66 !important;
    text-align: center !important;
    font-size: 22px !important;
    font-weight: 700 !important;
    padding: 22px !important;
    border-bottom: 1px solid #e5edf7 !important;
}

/* Login form */
.panel-body {
    background: #ffffff !important;
    padding: 30px !important;
}

/* Labels */
.form-group label {
    color: #23415f !important;
    font-weight: 600 !important;
}

/* Input fields */
.form-control {
    height: 46px !important;
    border: 1px solid #cbd9e8 !important;
    border-radius: 9px !important;
    box-shadow: none !important;
    font-size: 14px !important;
    padding: 10px 14px !important;
}

.form-control:focus {
    border-color: #1976d2 !important;
    box-shadow: 0 0 0 3px rgba(25,118,210,0.12) !important;
}

/* Login button */
.btn-primary {
    width: 100% !important;
    height: 46px !important;
    border: none !important;
    border-radius: 9px !important;
    background: linear-gradient(90deg, #1976d2, #1565c0) !important;
    font-size: 15px !important;
    font-weight: 700 !important;
}

.btn-primary:hover {
    box-shadow: 0 6px 15px rgba(25,118,210,0.25) !important;
}

/* Forgot password */
a {
    color: #1976d2 !important;
    font-weight: 500 !important;
}
